<section class="card"><h2><?= View::t('backup_restore') ?></h2><form method="post" action="<?= View::e($basePath) ?>/admin/settings/backup"><?= View::csrf() ?><button><?= View::t('create_download_backup') ?></button></form><h3><?= View::t('stored_backups') ?></h3><ul class="backup-list"><?php foreach($backups as $backup): ?><li><span><code><?= View::e($backup['name']) ?></code><small><?= View::e(number_format($backup['size']/1024,1,',',' ')) ?> KiB</small></span><form method="post" action="<?= View::e($basePath) ?>/admin/settings/backup/delete"><?= View::csrf() ?><input type="hidden" name="name" value="<?= View::e($backup['name']) ?>"><button class="danger-button action-button"><?= View::t('delete') ?></button></form></li><?php endforeach; ?><?php if(!$backups): ?><li><?= View::t('none') ?></li><?php endif; ?></ul><hr>
