<section class="card"><h2><?= View::t('printer_sorting') ?></h2><p class="muted"><?= View::t('printer_sorting_help') ?></p><form method="post" action="<?= View::e($basePath) ?>/admin/settings/printer-sort"><?= View::csrf() ?><label><?= View::t('printer_sort_mode') ?><select name="printer_sort_mode"><?php foreach(['az','za','custom'] as $mode): ?><option value="<?= $mode ?>" <?= $printerSortMode===$mode?'selected':'' ?>><?= View::t('printer_sort_'.$mode) ?></option><?php endforeach; ?></select></label><button><?= View::t('save') ?></button></form></section>
