</strong><br><small><?= View::e($device['platform']) ?></small></td><td><?= View::e($device['display_name']?:$device['username']) ?></td><td><?= View::e($device['app_version']?:'—') ?></td><td><?= View::e(View::dateTime($device['last_seen_at']?:$device['created_at'])) ?> UTC</td><td><form method="post" action="<?= View::e($basePath) ?>/admin/settings/device/delete"><?= View::csrf() ?><input type="hidden" name="id" value="<?= View::e($device['id']) ?>"><button class="danger-button action-button"><?= View::t('delete') ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></details><?php endif; ?></section>
